elling_price','name'=>'Selling Price'],['id'=>'mrp','name'=>'MRP']],'id','name',$selected['discount_basis']??'selling_price') ?></select></div><div class="form-group col-md-3"><label for="promotion-type">Discount Type</label><select class="form-control form-control-sm" id="promotion-type" name="discount_type"><?php echo $suiteSelect([['id'=>'percentage','name'=>'Percentage'],['id'=>'fixed','name'=>'Fixed Amount per Base Unit']],'id','name',$selected['discount_type']??'percentage') ?></select></div></div>
